// The skill's row (sorted by id), or null: a skill the kit does not list (the caller falls back to its tree).
inline const SkillFx* SkillFxOf(int id) {
    int lo = 0, hi = SkillFxCount - 1;
    while (lo <= hi) {
        const int mid = (lo + hi) / 2, v = SkillFxTable[mid].id;
        if (v == id) return &SkillFxTable[mid];
        if (v < id) lo = mid + 1; else hi = mid - 1;
    }
    return nullptr;
}
